import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"50、【鼎】 巽下離上","description":"周易尚氏學 - 50、【鼎】 巽下離上","frontmatter":{"title":"50、【鼎】 巽下離上","description":"周易尚氏學 - 50、【鼎】 巽下離上"},"headers":[],"relativePath":"classics/shangshi/055.md","filePath":"classics/shangshi/055.md"}'),s={name:"classics/shangshi/055.md"};function h(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_50、【鼎】-巽下離上" tabindex="-1">50、【鼎】 巽下離上 <a class="header-anchor" href="#_50、【鼎】-巽下離上" aria-label="Permalink to “50、【鼎】 巽下離上”">​</a></h1><p>元謂五。得位有應。故吉亨。端木國瑚曰。鼎之象不在鼎。而在伏象屯。屯下震為足。互坤為腹。上坎為耳。為鉉。凡鼎之象無一不備。後人不知易於正伏象不分。謂下陰為足。中三陽為腹。五陰為耳。易焉有巽足乾腹離耳之象哉。按端木氏說是也。二千年誤解。得是而正。其功甚偉。</p><p>彖曰。鼎。象也。以木巽火。亨飪也。聖人亨以享上帝。而大亨以養聖賢。巽而耳目聰明。柔進而上行。得中而應乎剛。是以元亨。</p><p>鼎之用在亨飪。以木巽火。鼎之用也。乾為聖人，高為目。兌為耳。六五為離兌主爻。故耳目聰明。虞翻謂三動成坎離。以坎為耳。後儒多從之。豈知三當位。焉能之不正。任意如此。何象不可得。按易林觀之中孚雲。鼎煬其耳。以中孚下兌為耳。比之豐雲。李耳匯鵲。亦以豐互兌為耳。蓋坎之為耳以其陷。兌亦坑坎也。故亦為耳。三爻鼎耳革。五爻鼎黃耳。象甚明也。</p><h3 id="象曰。木上有火。鼎。君子以正位凝命。" tabindex="-1">象曰。木上有火。鼎。君子以正位凝命。 <a class="header-anchor" href="#象曰。木上有火。鼎。君子以正位凝命。" aria-label="Permalink to “象曰。木上有火。鼎。君子以正位凝命。”">​</a></h3><p>鼎偏倚則勢危。故貴正。不正則束（左食）覆。鼎斂實於內。故貴凝。不凝則實漫矣。故君子取之。以正位凝命。</p><p>初六。鼎顛趾。利出否。得妾以其子。無咎。</p><p>震為趾。震伏巽隕。故曰顛趾。巽為臭腐。故曰否。否惡也汙也。初在下卑汙之地。出之四則各當位而利矣。四。兌為妾。四來初是得妾也。初之四體震。震為子。是得妾兼得子也。故利出也。</p><h3 id="象曰。鼎顛趾。未悖也。利出否。以從貴也。" tabindex="-1">象曰。鼎顛趾。未悖也。利出否。以從貴也。 <a class="header-anchor" href="#象曰。鼎顛趾。未悖也。利出否。以從貴也。" aria-label="Permalink to “象曰。鼎顛趾。未悖也。利出否。以從貴也。”">​</a></h3><p>停逆也。初陰順陽。故曰未悖。初承陽應四。故曰從貴。</p><p>九二。鼎有實。我仇有疾。不我能即。吉。</p><p>乾為實。仇匹也。指五。五乘陽勢逆。不能即二，故曰有疾。豫六五乘剛曰貞疾。茲與之同。我謂二。二為三四所隔。既不能即五。五因乘剛有疾。亦不能即二。然我與我仇。究為正應。始雖阻。終必合也。故結之曰吉。象曰終無尤。即謂二五終合也。</p><h3 id="象曰。鼎有實。慎所之也。我仇有疾。終無尤也。" tabindex="-1">象曰。鼎有實。慎所之也。我仇有疾。終無尤也。 <a class="header-anchor" href="#象曰。鼎有實。慎所之也。我仇有疾。終無尤也。" aria-label="Permalink to “象曰。鼎有實。慎所之也。我仇有疾。終無尤也。”">​</a></h3><p>之往也。二前臨重陽。行不利。故慎所之。二五終合。故終無尤。按此爻舊解。鮮有當者。一仇字失詁。虞翻謂二據四婦。四為仇。朱子以仇為初。陽遇陽為敵之義。自漢失傳。故慎所之三字。皆莫知所謂。清儒以漢為步趨。漢儒誤遂無不誤矣。</p><p>九三。鼎耳革。其行塞。雉膏不食。方雨虧悔。終吉。</p><p>三至五兌為耳。巽隕落。故曰耳革。行。道也。易林復之中孚雲。鼎煬其耳。熱不可舉。大路壅塞。旅人心苦。以行為道路。蓋三承乘皆陽。陽遇陽故其行塞。上離為雉。兌為膏。雉膏在上。乃上不應三。故雉膏不食。兌為雨。為昧。故曰虧悔。虧悔不明也。吳先生雲悔晦也。按易林復之雲。陰霧作匿。不見白日。不見白日。虧也。於虛賦日月蔽虧。江淹詩金峰各虧日。是也。陰霧作匿晦也。吳讀與易林同也。終吉者。初之四則三臨重陰。陽得陰則通。故吉。</p><h3 id="象曰。鼎耳革閱失其義也。" tabindex="-1">象曰。鼎耳革閱失其義也。 <a class="header-anchor" href="#象曰。鼎耳革閱失其義也。" aria-label="Permalink to “象曰。鼎耳革閱失其義也。”">​</a></h3><p>義宜也。鼎之用全在耳。今耳革失其用。故曰失義。</p><p>九四。鼎折足，覆公餗，餗其形渥，兇。</p><p>震為足。三至五兌。兌二折震。震象毀。故曰鼎折足。糞為束（左食）。馬雲鍵也。鄭雲菜也。乃三至五巽覆。四為諸候。三公之位。故曰覆公束（左食）。刑屋（右 ）王弼作形渥。古青同通用。管子心術下雲。意然後刑。刑然後思。注意感其事。然後呈形。是刑形古通用。茲從各家。京雲刑在頁（左九）為屋（右 ）。漢書敘傳。底劇鼎臣。師古注劇（左屋）厚刑。又周禮秋官司 氏。邦若屋誅。鄭注云屋當讀為其刑劇之束（左食）。劇（左屋）誅謂不於市也。蓋四不當位。故象兇。如是賣束（左食）之象。按易林未濟之無妄雲。求糜耕田。以無妄互巽為糜。而馬氏訓束（左食）為健。與易林同。鍵即糜也。鄭氏訓為菜。按韓奕之詩曰。其敕（上草）維何。維荀及蒲。疏引易曰鼎折足。覆公敕（上草）。是束（左食）與敕（上草）通用。而鄭訓與詩合。蓋皆巽象。可從。九家雲。三公調陰陽。猶鼎之凋五味。足折束（左食）覆。猶三公不勝其任。而覆天子之美。故受此重辜也。王弼以形渥為沾儒。程子謂為汗澀。豈知下系雲。德薄而位尊。鮮不及矣。謂及於刑辟也。即讀為刑劇（左屋）也。工程所釋。皆望文生義。非也。</p><h3 id="覆公餗-信如何也。" tabindex="-1">覆公餗，信如何也。 <a class="header-anchor" href="#覆公餗-信如何也。" aria-label="Permalink to “覆公餗，信如何也。”">​</a></h3><p>乾為信。信如何者。言行為如此。信仰失也。</p><p>六五。鼎黃耳金鉉 利貞。</p><p>兌為耳。離黃中。故曰黃耳。乾為金。故曰金鉉。鉉與扃同。士冠禮設局鼎（上加帽）。鄭注扃今文為鉉。釋文扃鼎扛也。孔疏所謂貫鼎耳而扛之。是也。伏坎象也。六五得中。下有應。故利貞。利貞言二五應也。</p><h3 id="象曰。鼎黃耳。中以為實也" tabindex="-1">象曰。鼎黃耳。中以為實也 <a class="header-anchor" href="#象曰。鼎黃耳。中以為實也" aria-label="Permalink to “象曰。鼎黃耳。中以為實也”">​</a></h3><p>乾為實。九二雲。鼎有實。五得中應二。故中以為實。實指二。黃中色。故曰中以為實。</p><p>上九。鼎玉鉉。大吉無不利。</p><p>乾為玉。上九陽為直。故象玉鉉。又上九以鉉舉鼎。動作自如。無有滯礙。故大吉無不利。與大畜上九義同。象釋曰剛柔節。以五陰為承也。</p><h3 id="象日。玉鉉在上。剛柔節也。" tabindex="-1">象日。玉鉉在上。剛柔節也。 <a class="header-anchor" href="#象日。玉鉉在上。剛柔節也。" aria-label="Permalink to “象日。玉鉉在上。剛柔節也。”">​</a></h3><p>上陽得五陰為承。故曰剛柔節。諸家多以三變應上成未濟。為剛柔節。豈知六爻獨三當位。胡可使其失正。且變而成未濟。六爻皆不安。胡能大吉。此自虞翻卦變伎倆。以濟其窮者。可復申述之乎。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
